; DMX512 transmitter; start code and 511 slots from tape words 0-127, refreshed continuously
; Generated by escgen from protocols/dmx512_tx.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: ANSI E1.11-2008 (DMX512-A), Table 6: transmitted break 92 us min, mark after break 12 us min, 250 kbit/s, slots of 1 start, 8 data LSB first, 2 stop bits
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ BIT, CLK_KHZ // 250
.equ BREAK, CLK_KHZ * 100 // 1000
.equ MAB, CLK_KHZ * 12 // 1000
.default PIN_TX, 0
.equ P_TX, 1 << PIN_TX
.equ TAPE_END, 128

.own  PIN_TX, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_TX, P_TX, P_TX            ; idle levels
    ADDT  1
packet:
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    EMIT  P_TX, 0, P_TX               ; break
    ADDT  BREAK
    EMIT  P_TX, P_TX, P_TX            ; mab
    ADDT  MAB
    MOVI  r2, 0                       ; tape address
next_word:
    LDT   r1, r2, 0
    EMIT  P_TX, 0, P_TX               ; start
    ADDT  BIT
    MOV   r0, r1                      ; 8 bits, LSB first
    LDSH  r0
    LDLC  8
bit1:
    EMITX P_TX, LSB, P_TX             ; data bit
    ADDT  BIT
    DJNZ  bit1
    SHR   r1, 8                       ; next field
    EMIT  P_TX, P_TX, P_TX            ; stop
    ADDT  2 * BIT
    EMIT  P_TX, 0, P_TX               ; start
    ADDT  BIT
    MOV   r0, r1                      ; 8 bits, LSB first
    LDSH  r0
    LDLC  8
bit2:
    EMITX P_TX, LSB, P_TX             ; data bit
    ADDT  BIT
    DJNZ  bit2
    SHR   r1, 8                       ; next field
    EMIT  P_TX, P_TX, P_TX            ; stop
    ADDT  2 * BIT
    EMIT  P_TX, 0, P_TX               ; start
    ADDT  BIT
    MOV   r0, r1                      ; 8 bits, LSB first
    LDSH  r0
    LDLC  8
bit3:
    EMITX P_TX, LSB, P_TX             ; data bit
    ADDT  BIT
    DJNZ  bit3
    SHR   r1, 8                       ; next field
    EMIT  P_TX, P_TX, P_TX            ; stop
    ADDT  2 * BIT
    EMIT  P_TX, 0, P_TX               ; start
    ADDT  BIT
    MOV   r0, r1                      ; 8 bits, LSB first
    LDSH  r0
    LDLC  8
bit4:
    EMITX P_TX, LSB, P_TX             ; data bit
    ADDT  BIT
    DJNZ  bit4
    EMIT  P_TX, P_TX, P_TX            ; stop
    ADDT  2 * BIT
    ADDI  r2, 1
    CMPI  r2, TAPE_END                ; Z after the last word
    JNZ   next_word
    JMP   packet
